window.CHAPTER_LOCAL=window.CHAPTER_LOCAL||{};window.CHAPTER_LOCAL["bree"]=JSON.parse("{\n  \"id\": \"bree\",\n  \"title\": \"Старый лес и Бри\",\n  \"roman\": \"II\",\n  \"startSteps\": 156000,\n  \"startKm\": 117,\n  \"totalKm\": 100,\n  \"totalSteps\": 133333,\n  \"endSteps\": 289333,\n  \"stepMeters\": 0.75,\n  \"source\": {\n    \"file\": \"route-master.xlsx\",\n    \"sha256\": \"a93611798140021a39fda53dedc05cc1a5f2147a375a80e35634f40c52eb5c50\",\n    \"sheet\": \"2. Старый лес и Бри\",\n    \"thresholds\": \"global, column I\",\n    \"textColumn\": \"L\",\n    \"versionEvidence\": \"20/22 populated events; 100/169 km; CAVE-01/02. Workbook metadata has no version label.\"\n  },\n  \"segments\": [\n    {\n      \"id\": 8,\n      \"from\": \"Крикхоллоу\",\n      \"to\": \"Старый лес\",\n      \"km\": 24,\n      \"startSteps\": 156000,\n      \"endSteps\": 188000,\n      \"geographicStatus\": \"Проверить\",\n      \"geographicNote\": \"Крикхоллоу расположено недалеко от живой изгороди Старого леса; 24 км может быть многовато.\"\n    },\n    {\n      \"id\": 9,\n      \"from\": \"Старый лес\",\n      \"to\": \"Дом Тома Бомбадила\",\n      \"km\": 16,\n      \"startSteps\": 188000,\n      \"endSteps\": 209333,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Положение старта «Старый лес» условное.\"\n    },\n    {\n      \"id\": 10,\n      \"from\": \"Дом Тома Бомбадила\",\n      \"to\": \"Упокоища\",\n      \"km\": 26,\n      \"startSteps\": 209333,\n      \"endSteps\": 244000,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Курганы — отдельная область, не конкретная точка.\"\n    },\n    {\n      \"id\": 11,\n      \"from\": \"Упокоища\",\n      \"to\": \"Брыль\",\n      \"km\": 34,\n      \"startSteps\": 244000,\n      \"endSteps\": 289333,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Сверить с картой и дорожной сетью.\"\n    }\n  ],\n  \"events\": [\n    {\n      \"id\": \"bree-001\",\n      \"chapterId\": \"bree\",\n      \"order\": 1,\n      \"title\": \"Северные ворота Заскочья\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 8,\n      \"from\": \"Крикхоллоу\",\n      \"to\": \"Старый лес\",\n      \"segmentKm\": 4.8,\n      \"km\": 121.8,\n      \"steps\": 162400,\n      \"stepsSincePrevious\": 6400,\n      \"text\": \"У северных ворот Заскочья кончаются знакомые хоббитские дороги, а впереди темнеет стена леса. На старом столбе у обочины ещё можно разобрать предостережение путникам.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-001.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-001-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-002\",\n      \"chapterId\": \"bree\",\n      \"order\": 2,\n      \"title\": \"Высокий Заплот\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 8,\n      \"from\": \"Крикхоллоу\",\n      \"to\": \"Старый лес\",\n      \"segmentKm\": 9.6,\n      \"km\": 126.6,\n      \"steps\": 168800,\n      \"stepsSincePrevious\": 6400,\n      \"text\": \"В Высоком Заплоте почти скрылась под листьями узкая калитка, ведущая в Старый лес. Стоит шагнуть за неё, и привычный шум Шира остаётся позади.\",\n      \"reward\": {\n        \"id\": \"bree-002-reward\",\n        \"name\": \"За пределами знакомого\",\n        \"kind\": \"Достижение\",\n        \"icon\": \"✧\",\n        \"description\": \"\",\n        \"cardText\": \"Достижение · За пределами знакомого\",\n        \"badgePrompt\": \"Круглый латунный значок с приоткрытой деревянной калиткой в живой изгороди, за калиткой — тёмные стволы; древняя гравировка, без надписей.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Достижение · За пределами знакомого\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Круглый латунный значок с приоткрытой деревянной калиткой в живой изгороди, за калиткой — тёмные стволы; древняя гравировка, без надписей.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-002.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-002-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-003\",\n      \"chapterId\": \"bree\",\n      \"order\": 3,\n      \"title\": \"Тенистый проход\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 8,\n      \"from\": \"Крикхоллоу\",\n      \"to\": \"Старый лес\",\n      \"segmentKm\": 14.4,\n      \"km\": 131.4,\n      \"steps\": 175200,\n      \"stepsSincePrevious\": 6400,\n      \"text\": \"Под сомкнутыми ветвями даже полуденный свет кажется сумеречным. Узкая тропа теряется в густом кустарнике, словно лес нарочно прячет дорогу.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-003.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-003-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-004\",\n      \"chapterId\": \"bree\",\n      \"order\": 4,\n      \"title\": \"Кривые корни\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 8,\n      \"from\": \"Крикхоллоу\",\n      \"to\": \"Старый лес\",\n      \"segmentKm\": 19.2,\n      \"km\": 136.2,\n      \"steps\": 181600,\n      \"stepsSincePrevious\": 6400,\n      \"text\": \"Корни вековых деревьев переплелись поперёк тропы причудливыми узлами. Обойдя их, путник с удивлением обнаруживает знакомый ориентир совсем не с той стороны.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-004.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-004-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-005\",\n      \"chapterId\": \"bree\",\n      \"order\": 5,\n      \"title\": \"Старый лес\",\n      \"type\": \"Локация\",\n      \"segment\": 8,\n      \"from\": \"Крикхоллоу\",\n      \"to\": \"Старый лес\",\n      \"segmentKm\": 24,\n      \"km\": 141,\n      \"steps\": 188000,\n      \"stepsSincePrevious\": 6400,\n      \"text\": \"Старый лес встречает тяжёлыми кронами, сырой землёй и тишиной, в которой слышен каждый шорох. Кажется, здешние деревья сами выбирают, куда поведут тропы.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-005.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-005-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"bree-006\",\n      \"chapterId\": \"bree\",\n      \"order\": 6,\n      \"title\": \"Овраг в Старом лесу\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 9,\n      \"from\": \"Старый лес\",\n      \"to\": \"Дом Тома Бомбадила\",\n      \"segmentKm\": 4,\n      \"km\": 145,\n      \"steps\": 193333,\n      \"stepsSincePrevious\": 5333,\n      \"text\": \"В глубоком овраге пахнет мокрой листвой, а звук шагов глохнет между земляными склонами. Среди корней виднеется старая деревянная пуговица — маленький след чужого путешествия.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-006.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-006-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-007\",\n      \"chapterId\": \"bree\",\n      \"order\": 7,\n      \"title\": \"Тропа у Ивлинки\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 9,\n      \"from\": \"Старый лес\",\n      \"to\": \"Дом Тома Бомбадила\",\n      \"segmentKm\": 8,\n      \"km\": 149,\n      \"steps\": 198667,\n      \"stepsSincePrevious\": 5334,\n      \"text\": \"Тропа спускается к Ивлинке, чья тёмная вода лениво течёт под нависшими ветвями. Ивы склоняются так низко, будто берегут реку от посторонних глаз.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-007.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-007-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-008\",\n      \"chapterId\": \"bree\",\n      \"order\": 8,\n      \"title\": \"Древний вяз\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 9,\n      \"from\": \"Старый лес\",\n      \"to\": \"Дом Тома Бомбадила\",\n      \"segmentKm\": 12,\n      \"km\": 153,\n      \"steps\": 204000,\n      \"stepsSincePrevious\": 5333,\n      \"text\": \"Под ветвями древнего вяза лежит густая прохладная тень, так и манящая устроить привал. Но шелест кроны всё больше напоминает недовольное бормотание, и задерживаться здесь не хочется.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-008.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-008-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-009\",\n      \"chapterId\": \"bree\",\n      \"order\": 9,\n      \"title\": \"Дом Тома Бомбадила\",\n      \"type\": \"Локация\",\n      \"segment\": 9,\n      \"from\": \"Старый лес\",\n      \"to\": \"Дом Тома Бомбадила\",\n      \"segmentKm\": 16,\n      \"km\": 157,\n      \"steps\": 209333,\n      \"stepsSincePrevious\": 5333,\n      \"text\": \"Из лесной чащи доносится весёлая песня Тома Бомбадила, а вскоре среди деревьев появляется его гостеприимный дом. Здесь ждут Златеника, тёплый ужин и рассказы о временах, когда лес был ещё моложе.\",\n      \"reward\": {\n        \"id\": \"bree-009-reward\",\n        \"name\": \"Лента Златеники\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Лента Златеники\",\n        \"badgePrompt\": \"Свободно завязанная золотистая шёлковая лента, лёгкая переливчатая ткань, небольшой листок на узле; предметная живописная миниатюра.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Лента Златеники\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Свободно завязанная золотистая шёлковая лента, лёгкая переливчатая ткань, небольшой листок на узле; предметная живописная миниатюра.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-009.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-009-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"bree-010\",\n      \"chapterId\": \"bree\",\n      \"order\": 10,\n      \"title\": \"Тропа из дома Бомбадила\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 10,\n      \"from\": \"Дом Тома Бомбадила\",\n      \"to\": \"Упокоища\",\n      \"segmentKm\": 5.2,\n      \"km\": 162.2,\n      \"steps\": 216267,\n      \"stepsSincePrevious\": 6934,\n      \"text\": \"От дома Бомбадила тропа ведёт к открытым холмам, и последние слова его напутствия ещё звучат в памяти. За спиной затихает знакомая песня, а впереди поднимается прохладный ветер.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-010.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-010-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-011\",\n      \"chapterId\": \"bree\",\n      \"order\": 11,\n      \"title\": \"Открытые холмы\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 10,\n      \"from\": \"Дом Тома Бомбадила\",\n      \"to\": \"Упокоища\",\n      \"segmentKm\": 10.4,\n      \"km\": 167.4,\n      \"steps\": 223200,\n      \"stepsSincePrevious\": 6933,\n      \"text\": \"Деревья расступаются, открывая бескрайние травяные склоны под высоким небом. Вдали виднеются округлые насыпи древних курганов, хранящих чужие, давно забытые истории.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-011.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-011-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-012\",\n      \"chapterId\": \"bree\",\n      \"order\": 12,\n      \"title\": \"Первый курган\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 10,\n      \"from\": \"Дом Тома Бомбадила\",\n      \"to\": \"Упокоища\",\n      \"segmentKm\": 15.6,\n      \"km\": 172.6,\n      \"steps\": 230133,\n      \"stepsSincePrevious\": 6933,\n      \"text\": \"Первый курган поднимается над травой невысоким зелёным холмом, окружённым мелкими камнями. Здесь нет ни домов, ни дорог, и только ветер тревожит сухие стебли.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-012.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-012-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-013\",\n      \"chapterId\": \"bree\",\n      \"order\": 13,\n      \"title\": \"Холодный туман\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 10,\n      \"from\": \"Дом Тома Бомбадила\",\n      \"to\": \"Упокоища\",\n      \"segmentKm\": 20.8,\n      \"km\": 177.8,\n      \"steps\": 237067,\n      \"stepsSincePrevious\": 6934,\n      \"text\": \"Белый туман медленно стелется между холмами, стирая дальние очертания. Лишь редкие камни у тропы помогают не потерять направление.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-013.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-013-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-014\",\n      \"chapterId\": \"bree\",\n      \"order\": 14,\n      \"title\": \"Холмы Упокоищ\",\n      \"type\": \"Локация\",\n      \"segment\": 10,\n      \"from\": \"Дом Тома Бомбадила\",\n      \"to\": \"Упокоища\",\n      \"segmentKm\": 26,\n      \"km\": 183,\n      \"steps\": 244000,\n      \"stepsSincePrevious\": 6933,\n      \"text\": \"Холмы Упокоищ встречают древними насыпями и почти неподвижной тишиной. Издалека словно доносится обрывок песни Бомбадила, напоминая, что даже здесь путь продолжается.\",\n      \"reward\": {\n        \"id\": \"bree-014-reward\",\n        \"name\": \"Старинный медальон\",\n        \"kind\": \"Секрет\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Секрет · Старинный медальон\",\n        \"badgePrompt\": \"Потемневший овальный бронзовый медальон со стёртым растительным рельефом и зелёной патиной, найденный в древнем кургане.\",\n        \"conditional\": true,\n        \"condition\": {\n          \"branchId\": \"CAVE-01\",\n          \"requires\": \"completed\"\n        }\n      },\n      \"rewardSource\": \"Секрет · Старинный медальон\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Потемневший овальный бронзовый медальон со стёртым растительным рельефом и зелёной патиной, найденный в древнем кургане.\",\n      \"optionalBranch\": {\n        \"id\": \"CAVE-01\",\n        \"enabled\": false,\n        \"triggerEventId\": \"bree-014\",\n        \"extraKm\": 3,\n        \"extraSteps\": 4000,\n        \"rewardText\": \"Секрет · «Старинный медальон» — Древняя реликвия из скрытой погребальной камеры.\",\n        \"badgePrompt\": \"Потемневший овальный бронзовый медальон со стёртым растительным рельефом и зелёной патиной, найденный в древнем кургане.\"\n      },\n      \"image\": \"assets/illustrations/bree/bree-014.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-014-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"bree-015\",\n      \"chapterId\": \"bree\",\n      \"order\": 15,\n      \"title\": \"Тропа среди курганов\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 11,\n      \"from\": \"Упокоища\",\n      \"to\": \"Бри\",\n      \"segmentKm\": 5.67,\n      \"km\": 188.67,\n      \"steps\": 251560,\n      \"stepsSincePrevious\": 7560,\n      \"text\": \"Узкая тропа петляет между заросшими курганами, где из земли выглядывают обломки старой кладки. На одном из камней ещё сохранился полустёртый резной узор.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-015.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-015-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-016\",\n      \"chapterId\": \"bree\",\n      \"order\": 16,\n      \"title\": \"Старая дорога\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 11,\n      \"from\": \"Упокоища\",\n      \"to\": \"Бри\",\n      \"segmentKm\": 11.33,\n      \"km\": 194.33,\n      \"steps\": 259107,\n      \"stepsSincePrevious\": 7547,\n      \"text\": \"Из высокой травы снова проступает старая мощёная дорога, давно пережившая своих строителей. Вдалеке уже угадывается дым над крышами обжитого края.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-016.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-016-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-017\",\n      \"chapterId\": \"bree\",\n      \"order\": 17,\n      \"title\": \"Путевой камень\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 11,\n      \"from\": \"Упокоища\",\n      \"to\": \"Бри\",\n      \"segmentKm\": 17,\n      \"km\": 200,\n      \"steps\": 266667,\n      \"stepsSincePrevious\": 7560,\n      \"text\": \"Путевой камень почти целиком укрылся мхом и осел в землю. Под зелёным покровом обнаруживается стёртая стрелка, указывающая в сторону Брыли.\",\n      \"reward\": {\n        \"id\": \"bree-017-reward\",\n        \"name\": \"Оттиск старой дороги\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Оттиск старой дороги\",\n        \"badgePrompt\": \"Небольшой лист плотной кремовой бумаги с угольным оттиском древней путевой стрелки и фактурой камня, края слегка потрёпаны.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Оттиск старой дороги\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Небольшой лист плотной кремовой бумаги с угольным оттиском древней путевой стрелки и фактурой камня, края слегка потрёпаны.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-017.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-017-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-018\",\n      \"chapterId\": \"bree\",\n      \"order\": 18,\n      \"title\": \"Западные ворота Бри\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 11,\n      \"from\": \"Упокоища\",\n      \"to\": \"Бри\",\n      \"segmentKm\": 22.67,\n      \"km\": 205.67000000000002,\n      \"steps\": 274227,\n      \"stepsSincePrevious\": 7560,\n      \"text\": \"У западных ворот Брыли путника встречает любопытный привратник, охотно расспрашивающий о дороге. За воротами слышны голоса жителей и пахнет дымом домашних очагов.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-018.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-018-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-019\",\n      \"chapterId\": \"bree\",\n      \"order\": 19,\n      \"title\": \"Оживленная улица\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 11,\n      \"from\": \"Упокоища\",\n      \"to\": \"Бри\",\n      \"segmentKm\": 28.33,\n      \"km\": 211.32999999999998,\n      \"steps\": 281773,\n      \"stepsSincePrevious\": 7546,\n      \"text\": \"По оживлённой улице Брыли катят повозки, цокают копыта и перекликаются торговцы. Среди вывесок постоялых дворов легко заметить дорогу к знаменитому «Резвому Пони».\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-019.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-019-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"bree-020\",\n      \"chapterId\": \"bree\",\n      \"order\": 20,\n      \"title\": \"Бри: «Резвый Пони»\",\n      \"type\": \"Глава\",\n      \"segment\": 11,\n      \"from\": \"Упокоища\",\n      \"to\": \"Бри\",\n      \"segmentKm\": 34,\n      \"km\": 217,\n      \"steps\": 289333,\n      \"stepsSincePrevious\": 7560,\n      \"text\": \"За дверями «Резвого Пони» шумят голоса, потрескивает огонь и звенят кружки. В тёплом общем зале можно передохнуть и услышать немало историй о далёких дорогах и загадочном Бродяжнике.\",\n      \"reward\": {\n        \"id\": \"bree-020-reward\",\n        \"name\": \"Оловянная подкова\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Оловянная подкова\",\n        \"badgePrompt\": \"Миниатюрная оловянная подковка на коротком кожаном шнуре, простая дорожная сувенирная вещица с мягкими потёртостями.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Оловянная подкова\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Миниатюрная оловянная подковка на коротком кожаном шнуре, простая дорожная сувенирная вещица с мягкими потёртостями.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/bree/bree-020.webp\",\n      \"thumbnail\": \"assets/illustrations/bree/bree-020-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    }\n  ]\n}");
